import re, csv
ttl=open(GRAPH_TTL).read()
# build room -> label map
roomlabel={}
for m in re.finditer(r"(bldg:[\w]+)\s+a\s+brick:Room\s*;\s*\n\s*rdfs:label\s*\"([^\"]*)\"", ttl):
    roomlabel[m.group(1)]=m.group(2)
# build room -> occupancy sensor series id
room_occ={}
for m in re.finditer(r"bldg:([\w]+)\.Occupancy_Sensor\s+a\s+brick:Occupancy_Sensor\s*;\s*\n\s*brick:hasLocation\s+bldg:([\w]+)\s*;\s*\n\s*brick:isPointOf\s+bldg:([\w]+)\s*;\s*\n\s*ref:hasExternalReference\s*<urn:buildgraph:tsref:([\w-]+)>", ttl):
    # hasLocation gives the room
    room_occ[m.group(2)] = m.group(4)
# Actually the sensor name's room is group1, hasLocation group2. Use group2.
for room,lab in roomlabel.items():
    z=lab.split(" ")[0] if " " in lab else lab
    if z in ("Perimeter_mid_ZN_1","Perimeter_bot_ZN_2"):
        print(lab, "room=",room, "occ_series=",room_occ.get(room))
from collections import defaultdict
d=defaultdict(list)
for room,lab in roomlabel.items():
    z=lab.split(" ")[0] if " " in lab else lab
    d[z].append((lab,room,room_occ.get(room)))
for z in ("Perimeter_mid_ZN_1","Perimeter_bot_ZN_2"):
    print("=== ",z)
    for x in sorted(d[z]): print(x)

import re
ttl=open(GRAPH_TTL).read()
# Match all Occupancy_Sensor blocks and capture hasLocation room
occ={}
for m in re.finditer(r"(bldg:\w+)\.Occupancy_Sensor\s+a\s+brick:Occupancy_Sensor\s*;\s*\n\s*brick:hasLocation\s+(bldg:\w+)\s*;\s*\n\s*brick:isPointOf\s+(bldg:\w+)\s*;\s*\n\s*ref:hasExternalReference\s*<ur?n:buildgraph:tsref:([\w-]+)>", ttl):
    occ.setdefault(m.group(3), {})[m.group(2)] = m.group(4)
# Actually key by room (group2? or group3?). isPointOf should be the point entity.
# Let's just map: room(hasLocation)=group2 -> series
m2={}
for m in re.finditer(r"brick:hasLocation\s+(bldg:\w+)\s*;\s*\n\s*brick:isPointOf\s+(bldg:\w+)\s*;\s*\n\s*ref:hasExternalReference\s*<ur?n:buildgraph:tsref:([\w-]+)>", ttl):
    m2.setdefault((m.group(1),m.group(2)),m.group(3))
# find pairs where a Occupancy_Sensor exists
pat=re.compile(r"(bldg:\w+)\.Occupancy_Sensor\s+a\s+brick:Occupancy_Sensor\s*;\s*\n\s*brick:hasLocation\s+(bldg:\w+)\s*;\s*\n\s*brick:isPointOf\s+(bldg:\w+)\s*;\s*\n\s*ref:hasExternalReference\s*<urn:buildgraph:tsref:([\w-]+)>",re.S)
res={}
for m in pat.finditer(ttl):
    res[m.group(2)]=m.group(4)
print(len(res), res)

import csv
cat={}
with open(CATALOG_CSV) as f:
    for x in csv.DictReader(f):
        cat[x["timeseries_id"]]=x
occ=[v for v in cat.values() if v["point_class"]=="Occupancy_Sensor"]
for v in occ:
    print(v["point_uri"], v["timeseries_id"], v["unit"], v["quantity_kind"])

